qss_template:
/* --- Global Base --- */
QWidget {
    background-color: {bg_app};
    color: {text_primary};
    font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", Roboto, "Cantarell", "Ubuntu", sans-serif;
    font-size: {ui_sz}pt;
    selection-background-color: {accent};
    selection-color: {accent_text};
    border: none;
    outline: none;
}

QMainWindow, QDialog {
    background-color: {bg_app};
}

/* --- Frameless Floating Popup --- */
QFrame#popupFrame {
    background-color: {bg_surface};
    border: {card_border};
    border-radius: 16px;
}

QFrame#popupFrame QLabel {
    background-color: transparent;
    color: {text_secondary};
}

QFrame#popupFrame QLabel#popupTitle {
    font-weight: 600;
    color: {accent};
    font-size: 13px;
    background-color: transparent;
}

QFrame#popupFrame QLabel#popupSubLabel {
    font-size: 11px;
    color: {text_muted};
    background-color: transparent;
}

QFrame#popupFrame QLabel#loadingLabel {
    color: {accent};
    font-size: 12px;
    font-weight: 500;
    background-color: transparent;
}

QLabel#detectedBadge, QFrame#popupFrame QLabel#detectedBadge {
    color: {accent};
    font-size: 11px;
    font-weight: 500;
    background-color: transparent;
}

/* Popup Text Areas */
QFrame#popupFrame QTextEdit {
    background-color: {bg_card};
    color: {text_primary};
    border: {card_border};
    border-radius: 10px;
    padding: 10px 12px;
    font-size: {txt_sz}pt;
    line-height: 1.4;
}

QFrame#popupFrame QTextEdit:focus {
    background-color: {bg_card_focus};
    border: {card_border};
}

/* Popup Searchable Dropdown */
QFrame#popupFrame QComboBox,
QFrame#popupFrame QComboBox:editable {
    background-color: {bg_input};
    color: {text_primary};
    border: {card_border};
    outline: none;
    border-radius: 8px;
    padding: 4px 10px;
    min-height: 24px;
    font-weight: 500;
}

QFrame#popupFrame QComboBox:focus,
QFrame#popupFrame QComboBox:editable:focus {
    border: {card_border};
    outline: none;
}

QFrame#popupFrame QComboBox QLineEdit,
QFrame#popupFrame QComboBox QLineEdit:focus {
    background-color: {bg_input};
    color: {text_primary};
    border: none;
    outline: none;
    border-radius: 6px;
    padding: 2px 4px;
    font-weight: 500;
    selection-background-color: {accent};
    selection-color: {accent_text};
}

QFrame#popupFrame QComboBox::drop-down {
    subcontrol-origin: padding;
    subcontrol-position: top right;
    width: 20px;
    border: none;
    background: transparent;
}

QFrame#popupFrame QComboBox QAbstractItemView {
    background-color: {bg_surface};
    color: {text_primary};
    border: 1px solid {text_muted}40;
    border-radius: 8px;
    padding: 4px;
    selection-background-color: {accent};
    selection-color: {accent_text};
    outline: none;
}

/* Styled Copy Buttons */
QPushButton#copyBtn,
QPushButton#popupCopyBtn {
    padding: 6px 16px;
    background-color: #333333;
    border-radius: 6px;
    font-weight: bold;
    color: #ffffff;
    border: none;
    outline: none;
    min-height: 28px;
}

QPushButton#copyBtn:hover,
QPushButton#popupCopyBtn:hover {
    background-color: #444444;
    color: #ffffff;
}

QPushButton#copyBtn:pressed,
QPushButton#popupCopyBtn:pressed {
    background-color: #222222;
    color: #ffffff;
}

QPushButton#popupPrimaryBtn {
    min-height: 32px;
    max-height: 32px;
    border-radius: 8px;
    padding: 6px 14px;
    font-size: 12px;
    border: none;
    outline: none;
    background-color: {accent};
    color: {accent_text};
    font-weight: 600;
}

QPushButton#popupPrimaryBtn:hover {
    background-color: {accent_hover};
    color: {accent_text};
}

QPushButton#popupPrimaryBtn:pressed {
    background-color: {accent_pressed};
    color: {accent_text};
}

/* --- Text Inputs & Cards --- */
QTextEdit, QPlainTextEdit {
    background-color: {bg_card};
    color: {text_primary};
    border: {card_border};
    border-radius: 12px;
    padding: 16px;
    font-size: {txt_sz}pt;
    line-height: 1.5;
}

QTextEdit:focus, QPlainTextEdit:focus {
    background-color: {bg_card_focus};
    border: {card_border};
}

QLineEdit {
    background-color: {bg_card};
    color: {text_primary};
    border: {card_border};
    border-radius: 8px;
    padding: 8px 12px;
}

QLineEdit:focus {
    background-color: {bg_card_focus};
    border: {card_border};
}

/* --- Ghost / Invisible Controls by default --- */
QPushButton {
    background-color: transparent;
    color: {text_secondary};
    border: none;
    border-radius: 8px;
    padding: 6px 14px;
    font-weight: 500;
}

QPushButton:hover {
    background-color: {hover_overlay};
    color: {text_primary};
}

QPushButton:pressed {
    background-color: {pressed_overlay};
    color: {text_primary};
}

QPushButton#primaryBtn {
    background-color: {accent};
    color: {accent_text};
    font-weight: 600;
}

QPushButton#primaryBtn:hover {
    background-color: {accent_hover};
    color: {accent_text};
}

QPushButton#closeBtn {
    background-color: transparent;
    color: {text_muted};
    border: none;
    font-size: 14px;
    font-weight: 600;
    min-width: 26px;
    max-width: 26px;
    min-height: 26px;
    max-height: 26px;
    border-radius: 6px;
    padding: 0px;
}

QPushButton#closeBtn:hover {
    background-color: {hover_overlay};
    color: {text_primary};
}

QPushButton#closeBtn:pressed {
    background-color: {pressed_overlay};
    color: {text_primary};
}

/* --- Microphone Button --- */
QPushButton#micBtn {
    background-color: transparent;
    color: {text_secondary};
    border: none;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 500;
    padding: 6px 12px;
}

QPushButton#micBtn:hover {
    background-color: {hover_overlay};
    color: {text_primary};
}

QPushButton#micBtn[active="true"] {
    background-color: rgba(239, 68, 68, 0.22);
    color: #f87171;
    font-weight: 600;
}

/* --- Circular Floating Swap Button --- */
QPushButton#swapBtn {
    background-color: {swap_btn_bg};
    border-radius: 16px;
    min-width: 32px;
    min-height: 32px;
    max-width: 32px;
    max-height: 32px;
    width: 32px;
    height: 32px;
    color: {swap_btn_text};
    font-size: 16px;
    font-weight: 500;
    border: none;
    outline: none;
    padding: 0px;
    margin: 0px;
}

QPushButton#swapBtn:hover {
    background-color: {swap_btn_hover};
    color: {swap_btn_text};
}

QPushButton#swapBtn:pressed {
    background-color: {accent};
    color: {accent_text};
}

/* --- Dropdowns --- */
QComboBox {
    background-color: {bg_card};
    color: {text_primary};
    border: {card_border};
    outline: none;
    border-radius: 8px;
    padding: 6px 14px;
    min-height: 24px;
    font-weight: 500;
}

QComboBox:hover {
    background-color: {bg_card_focus};
}

QComboBox:focus,
QComboBox:editable:focus {
    border: {card_border};
    outline: none;
}

QComboBox:editable {
    background-color: {bg_input};
    border: {card_border};
    outline: none;
}

QComboBox:editable:hover {
    background-color: {bg_input_focus};
}

QComboBox QLineEdit {
    background-color: {bg_input};
    color: {text_primary};
    border: none;
    outline: none;
    border-radius: 6px;
    padding: 2px 6px;
    font-weight: 500;
    selection-background-color: {accent};
    selection-color: {accent_text};
}

QComboBox QLineEdit:focus {
    background-color: {bg_input_focus};
    border: none;
    outline: none;
}

QComboBox::drop-down {
    subcontrol-origin: padding;
    subcontrol-position: top right;
    width: 24px;
    border: none;
    background: transparent;
}

QComboBox QAbstractItemView {
    background-color: {bg_surface};
    color: {text_primary};
    border: 1px solid {text_muted}40;
    border-radius: 8px;
    padding: 6px;
    selection-background-color: {item_selected};
    selection-color: {accent};
    outline: none;
}

/* --- Clean, Flat History List --- */
QPushButton#historyToggleBtn {
    background-color: transparent;
    color: {text_secondary};
    border: none;
    font-weight: 600;
    font-size: 13px;
    padding: 6px 10px;
    text-align: left;
    border-radius: 8px;
}

QPushButton#historyToggleBtn:hover {
    background-color: {item_hover};
    color: {text_primary};
}

QListWidget {
    background-color: transparent;
    color: {text_primary};
    border: none;
    padding: 2px 0px;
    outline: none;
}

QListWidget::item {
    background-color: transparent;
    border: none;
    border-radius: 8px;
    padding: 8px 12px;
    margin: 2px 0px;
}

QListWidget::item:hover {
    background-color: {item_hover};
    color: {text_primary};
}

QListWidget::item:selected {
    background-color: {item_selected};
    color: {accent};
}

/* --- Labels & Status --- */
QLabel {
    background-color: transparent;
    color: {text_secondary};
    border: none;
}

QLabel#sectionTitle, QLabel#popupTitle {
    font-weight: 600;
    color: {accent};
    font-size: 13px;
    background-color: transparent;
}

QLabel#popupSubLabel {
    font-size: 11px;
    color: {text_muted};
    background-color: transparent;
}

QLabel#spinnerLabel, QLabel#loadingLabel {
    color: {accent};
    font-size: 12px;
    font-weight: 500;
    background-color: transparent;
}

QStatusBar {
    background-color: transparent;
    color: {text_muted};
    border: none;
    font-size: 11px;
}

/* --- Invisible Draggable Splitter Handle (10px grab zone) --- */
QSplitter::handle {
    background-color: transparent;
    width: 10px;
}

QSplitter::handle:horizontal {
    background-color: transparent;
    width: 10px;
}

QSplitter::handle:vertical {
    background-color: transparent;
    height: 10px;
}

/* --- Minimalist Scrollbar (Thin, borderless, rounded) --- */
QScrollBar:vertical {
    border: none;
    background: transparent;
    width: 4px;
    margin: 0px;
}

QScrollBar::handle:vertical {
    background: {scrollbar_thumb};
    border-radius: 2px;
    min-height: 20px;
}

QScrollBar::handle:vertical:hover {
    background: {scrollbar_hover};
}

QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical,
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    border: none;
    background: transparent;
    height: 0px;
    width: 0px;
}

QScrollBar:horizontal {
    border: none;
    background: transparent;
    height: 4px;
    margin: 0px;
}

QScrollBar::handle:horizontal {
    background: {scrollbar_thumb};
    border-radius: 2px;
    min-width: 20px;
}

QScrollBar::handle:horizontal:hover {
    background: {scrollbar_hover};
}

QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal,
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    border: none;
    background: transparent;
    height: 0px;
    width: 0px;
}

/* --- Tabs & KeySequenceEdit --- */
QTabWidget::pane {
    border: none;
    background-color: transparent;
}

QTabBar::tab {
    background-color: transparent;
    color: {text_secondary};
    padding: 8px 16px;
    font-weight: 500;
    border-bottom: 2px solid transparent;
    margin-right: 4px;
}

QTabBar::tab:selected {
    color: {accent};
    border-bottom: 2px solid {accent};
    font-weight: 600;
}

QTabBar::tab:hover:!selected {
    color: {text_primary};
}

QKeySequenceEdit {
    background-color: {bg_card};
    color: {text_primary};
    border: {card_border};
    border-radius: 8px;
    padding: 8px 12px;
    font-weight: 500;
}

QKeySequenceEdit:focus {
    background-color: {bg_card_focus};
    border: {card_border};
}

/* --- Tooltips --- */
QToolTip {
    background-color: {bg_surface};
    color: {text_primary};
    border: 1px solid {text_muted}40;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 12px;
}

/* Minimalist Audio TTS Buttons */
QPushButton#ttsSourceBtn,
QPushButton#ttsTargetBtn {
    padding: 4px;
    background-color: transparent;
    border-radius: 6px;
    border: none;
    outline: none;
    min-width: 28px;
    max-width: 28px;
    min-height: 28px;
    max-height: 28px;
}

QPushButton#ttsSourceBtn:hover,
QPushButton#ttsTargetBtn:hover {
    background-color: {hover_overlay};
}

QPushButton#ttsSourceBtn[active="true"],
QPushButton#ttsTargetBtn[active="true"] {
    background-color: {item_selected};
}
